import { Button, ToasterProvider, useToaster } from '@gravity-ui/uikit';

function CornerButton() {
  const { add } = useToaster();

  const showToast = () => {
    add({
      name: `toast-${Date.now()}`,
      title: 'Уведомление',
      content: 'Это всплывающее уведомление скоро исчезнет само.',
      theme: 'info',
      autoHiding: true,
      timeout: 4000,
    });
  };

  return (
    <div style={{ position: 'fixed', right: 24, bottom: 24 }}>
      <Button view="action" size="l" onClick={showToast}>
        Показать уведомление
      </Button>
    </div>
  );
}

export function App() {
  return (
    <ToasterProvider>
      <div style={{ padding: 24 }}>
        <h1>Демо уведомлений</h1>
        <p>Нажмите кнопку в правом нижнем углу экрана.</p>
      </div>
      <CornerButton />
    </ToasterProvider>
  );
}

